from __future__ import annotations

from dataclasses import dataclass, replace
from decimal import Decimal, InvalidOperation
from typing import Protocol, TypeAlias


MoneyInput: TypeAlias = Decimal | int | float | str


class ShoppingCartError(Exception):
    """Base exception for shopping-cart errors."""


class InvalidProductNameError(ShoppingCartError):
    """Raised when a product name is empty or otherwise invalid."""


class InvalidUnitPriceError(ShoppingCartError):
    """Raised when a unit price is invalid."""


class InvalidQuantityError(ShoppingCartError):
    """Raised when an item quantity is invalid."""


class ItemNotFoundError(ShoppingCartError):
    """Raised when a requested product is not present in the cart."""


class ConflictingUnitPriceError(ShoppingCartError):
    """Raised when an existing product is added with a different unit price."""


class InvalidDiscountError(ShoppingCartError):
    """Raised when a discount amount or percentage is invalid."""


def _to_decimal(value: MoneyInput, *, field_name: str) -> Decimal:
    """Convert a supported numeric value to a finite Decimal."""
    if isinstance(value, bool):
        raise InvalidUnitPriceError(
            f"{field_name} must be numeric; Boolean values are not supported."
        )

    try:
        decimal_value = Decimal(str(value))
    except (InvalidOperation, TypeError) as error:
        raise InvalidUnitPriceError(
            f"{field_name} must be a valid numeric value; received {value!r}."
        ) from error

    if not decimal_value.is_finite():
        raise InvalidUnitPriceError(f"{field_name} must be finite.")

    return decimal_value


def _normalize_product_name(product_name: str) -> str:
    """Validate and normalize a product name."""
    if not isinstance(product_name, str):
        raise InvalidProductNameError("Product name must be a string.")

    normalized_name = product_name.strip()
    if not normalized_name:
        raise InvalidProductNameError("Product name must not be empty.")

    return normalized_name


def _validate_quantity(quantity: int) -> None:
    """Validate that a quantity is a positive integer."""
    if isinstance(quantity, bool) or not isinstance(quantity, int):
        raise InvalidQuantityError("Quantity must be an integer.")

    if quantity <= 0:
        raise InvalidQuantityError(
            f"Quantity must be greater than zero; received {quantity}."
        )


@dataclass(frozen=True, slots=True)
class CartItem:
    """An immutable product entry stored in a shopping cart."""

    product_name: str
    unit_price: Decimal
    quantity: int

    def __post_init__(self) -> None:
        """Validate and normalize the item's fields."""
        normalized_name = _normalize_product_name(self.product_name)
        object.__setattr__(self, "product_name", normalized_name)

        if not isinstance(self.unit_price, Decimal):
            raise InvalidUnitPriceError("CartItem unit price must be a Decimal.")

        if not self.unit_price.is_finite() or self.unit_price < Decimal("0"):
            raise InvalidUnitPriceError(
                f"Unit price must be finite and non-negative; "
                f"received {self.unit_price!r}."
            )

        _validate_quantity(self.quantity)

    @property
    def line_total(self) -> Decimal:
        """Return the item's unit price multiplied by its quantity."""
        return self.unit_price * self.quantity


class Discount(Protocol):
    """Interface implemented by shopping-cart discount strategies."""

    def calculate_discount(self, subtotal: Decimal) -> Decimal:
        """Return the discount amount for the supplied subtotal."""
        ...


@dataclass(frozen=True, slots=True)
class PercentageDiscount:
    """A discount calculated as a percentage of the subtotal."""

    percentage: Decimal

    def __post_init__(self) -> None:
        """Validate the percentage."""
        if not self.percentage.is_finite():
            raise InvalidDiscountError("Discount percentage must be finite.")

        if not Decimal("0") <= self.percentage <= Decimal("100"):
            raise InvalidDiscountError(
                "Discount percentage must be between 0 and 100 inclusive; "
                f"received {self.percentage}."
            )

    def calculate_discount(self, subtotal: Decimal) -> Decimal:
        """Return the percentage-based discount amount."""
        return subtotal * self.percentage / Decimal("100")


@dataclass(frozen=True, slots=True)
class FlatDiscount:
    """A fixed monetary discount applied to the subtotal."""

    amount: Decimal

    def __post_init__(self) -> None:
        """Validate the flat discount amount."""
        if not self.amount.is_finite() or self.amount < Decimal("0"):
            raise InvalidDiscountError(
                "Flat discount must be finite and non-negative; "
                f"received {self.amount}."
            )

    def calculate_discount(self, subtotal: Decimal) -> Decimal:
        """Return the applicable flat discount without exceeding the subtotal."""
        return min(self.amount, subtotal)


class ShoppingCart:
    """Manage cart items and an optional discount.

    Product names uniquely identify items. Adding an existing product increases
    its quantity, provided its unit price matches the existing unit price.
    Monetary calculations use ``Decimal`` to avoid binary floating-point errors.
    """

    def __init__(self) -> None:
        """Create an empty shopping cart with no active discount."""
        self._items: dict[str, CartItem] = {}
        self._discount: Discount | None = None

    def add_item(
        self,
        product_name: str,
        unit_price: MoneyInput,
        quantity: int = 1,
    ) -> CartItem:
        """Add an item and return its resulting cart entry.

        If the product already exists, its quantity is increased. An existing
        product cannot be added with a different unit price.
        """
        normalized_name = _normalize_product_name(product_name)
        normalized_price = self._normalize_unit_price(unit_price)
        _validate_quantity(quantity)

        existing_item = self._items.get(normalized_name)
        if existing_item is not None:
            if existing_item.unit_price != normalized_price:
                raise ConflictingUnitPriceError(
                    f"Product {normalized_name!r} already has unit price "
                    f"{existing_item.unit_price}; received {normalized_price}."
                )

            updated_item = replace(
                existing_item,
                quantity=existing_item.quantity + quantity,
            )
            self._items[normalized_name] = updated_item
            return updated_item

        new_item = CartItem(
            product_name=normalized_name,
            unit_price=normalized_price,
            quantity=quantity,
        )
        self._items[normalized_name] = new_item
        return new_item

    def remove_item(self, product_name: str) -> CartItem:
        """Remove a product by name and return the removed item."""
        normalized_name = _normalize_product_name(product_name)
        existing_item = self._get_item(normalized_name)
        del self._items[normalized_name]
        return existing_item

    def update_quantity(self, product_name: str, quantity: int) -> CartItem:
        """Set an existing product's quantity and return the updated item."""
        normalized_name = _normalize_product_name(product_name)
        _validate_quantity(quantity)

        existing_item = self._get_item(normalized_name)
        updated_item = replace(existing_item, quantity=quantity)
        self._items[normalized_name] = updated_item
        return updated_item

    def calculate_subtotal(self) -> Decimal:
        """Return the total price of all items before discounts."""
        return sum(
            (item.line_total for item in self._items.values()),
            start=Decimal("0"),
        )

    def apply_percentage_discount(self, percentage: MoneyInput) -> None:
        """Replace the active discount with a percentage discount."""
        normalized_percentage = self._normalize_discount_value(
            percentage,
            field_name="Discount percentage",
        )
        self._discount = PercentageDiscount(normalized_percentage)

    def apply_flat_discount(self, amount: MoneyInput) -> None:
        """Replace the active discount with a fixed monetary discount."""
        normalized_amount = self._normalize_discount_value(
            amount,
            field_name="Flat discount",
        )
        self._discount = FlatDiscount(normalized_amount)

    def clear_discount(self) -> None:
        """Remove the currently active discount."""
        self._discount = None

    def calculate_total(self) -> Decimal:
        """Return the subtotal after applying the active discount."""
        subtotal = self.calculate_subtotal()
        if self._discount is None:
            return subtotal

        discount_amount = self._discount.calculate_discount(subtotal)
        return max(Decimal("0"), subtotal - discount_amount)

    def list_items(self) -> tuple[CartItem, ...]:
        """Return an immutable snapshot of all cart items."""
        return tuple(self._items.values())

    def clear(self) -> None:
        """Remove all items and the active discount from the cart."""
        self._items.clear()
        self._discount = None

    def _get_item(self, normalized_product_name: str) -> CartItem:
        """Return an existing item or raise a descriptive exception."""
        try:
            return self._items[normalized_product_name]
        except KeyError as error:
            raise ItemNotFoundError(
                f"Product {normalized_product_name!r} is not in the cart."
            ) from error

    @staticmethod
    def _normalize_unit_price(unit_price: MoneyInput) -> Decimal:
        """Convert and validate a unit price."""
        normalized_price = _to_decimal(unit_price, field_name="Unit price")
        if normalized_price < Decimal("0"):
            raise InvalidUnitPriceError(
                f"Unit price must be non-negative; received {normalized_price}."
            )
        return normalized_price

    @staticmethod
    def _normalize_discount_value(
        value: MoneyInput,
        *,
        field_name: str,
    ) -> Decimal:
        """Convert a discount input and translate conversion failures."""
        try:
            return _to_decimal(value, field_name=field_name)
        except InvalidUnitPriceError as error:
            raise InvalidDiscountError(str(error)) from error
